import random

def binomial_simulation(n, p, trials=10000):
    successes = 0
    for _ in range(trials):
        count = sum(1 for _ in range(n) if random.random() < p)
        if count == 3:
            successes += 1
    return successes / trials

print(binomial_simulation(10, 0.3))
